// 打 开一个版本 库 git_repository *repo; int error = git_repository_open(&repo, "/path/to/repository"); // 逆 向 引 用 HEAD 到一个 提交 git_object *head_commit; error = git_revparse_single(&head_commit, repo, "HEAD^{commit}"); git_commit *commit = (git_commit*)head_commit; // 显 示 这个 提交 的一些 详 情 printf("%s", git_commit_message(commit)); const git_signature *author = git_commit_author(commit); printf("%s <%s>\n", author->name, author->email); const git_oid *tree_id = git_commit_tree_id(commit); // 清 理 现 场 git_commit_free(commit); git_repository_free(repo);
```

